def test_zip(zip_file, wordlist):
    with zipfile.ZipFile(zip_file) as z:
        with open(wordlist, 'r', errors='ignore') as f:
            for line in f:
                pwd = line.strip().encode()
                try:
                    z.extractall(pwd=pwd)
                    print(f'OK: {pwd.decode()}')
                    return True
                except:
